2.1 Жизненный цикл события: Логировать «Старт» и «Финиш» (Performance Mining)
Если сервис логирует только одну точку: log.Info(“Событие обработано”), Process Mining сможет построить только граф переходов, но он будет абсолютно слеп к задержкам. Мы никогда не узнаем, сколько задача лежала в очереди Kafka или сколько миллисекунд Whisper транскрибировал аудио.
Как правильно:
Каждая атомарная операция на микро-уровне должна генерировать два события в ClickHouse: статус START и статус COMPLETE.
Посмотрим на сервис FoodIngestionService Consumer со второй схемы. Когда он вычитывает пачку событий из топика purchase-events и пишет их в Business DB, внутри Go-кода это должно логироваться так:
// 1. Задача извлечена из Kafka — фиксируем НАЧАЛО обработки на микро-уровне
sendToClickHouse(EventLog{
    CaseID:       orderID,
    ActivityName: "Ingestion_Consumer_Write_DB",
    Stage:        "START", // Токен зашел в узел
    Timestamp:    time.Now(),
})

// ... здесь идет сама транзакция записи в Business DB ...

// 2. Транзакция успешно завершена — фиксируем КОНЕЦ обработки
sendToClickHouse(EventLog{
    CaseID:       orderID,
    ActivityName: "Ingestion_Consumer_Write_DB",
    Stage:        "COMPLETE", // Токен вышел из узла
    Timestamp:    time.Now(),
})

Что это дает в PM4Py: Библиотека берет Timestamp для START и COMPLETE одного и того же действия.

Разница между ними — это чистая скорость работы БД.
Разница между COMPLETE предыдущего сервиса-издателя (Publisher) и START текущего потребителя (Consumer) — это чистое время простоя сообщения внутри топиков Kafka! Мы видим лаг очередей без установки сложных внешних систем мониторинга Kafka.

3.2 Пример Go-кода (Dual-Stream In Action)

package main

import (
    "context"
    "log/slog"
    "os"
    "time"
)

// Инициализируем два разных логгера
var (
    // Stream 1: Системный логгер ошибок (Пишет в stdout для Vector)
    sysLogger = slog.New(slog.NewJSONHandler(os.Stdout, nil))

    // Stream 2: Логгер бизнес-событий для Process Mining (Отправляет напрямую в ClickHouse или специальный файл)
    pmLogger  = slog.New(slog.NewJSONHandler(os.Stderr, nil)) // Или кастомный коннектор к ClickHouse/Kafka
)

func ProcessReceiptTransaction(ctx context.Context, txID string, userID string, imageBase64 string) {
    // --- ТОЧКА 1: Фиксируем начало процесса для Process Mining ---
    pmLogger.Info("Process_Mining_Event",
        slog.String("case_id", txID),             // Сквозной ID сессии
        slog.Time("timestamp", time.Now()),       // Наносекунды
        slog.String("activity", "Receipt_OCR_Started"), // Имя шага
        slog.String("operator", userID),
    )

    // Имитируем запрос к ИИ-шлюзу на FastAPI
    err := callAiVisionGateway(imageBase64) 

    // --- ТОЧКА 2: Ветвление логики (Ошибка или Успех) ---
    if err != nil {
        // КЕЙС А: Произошел технический сбой (ИИ завис)

        // 1. Пишем в лог ошибок для разработчиков (Observability)
        sysLogger.Error("AI pipeline execution failed",
            slog.Time("timestamp", time.Now()),
            slog.String("trace_id", txID),
            slog.String("canonical_code", "AI_VISION_TIMEOUT"),
            slog.String("message", err.Error()),
            slog.String("stack_trace", "main.go:line 45... internal timeout"),
        )

        // 2. Фиксируем аварийный шаг в Process Mining, чтобы аналитики видели отклонение от графа
        pmLogger.Info("Process_Mining_Event",
            slog.String("case_id", txID),
            slog.Time("timestamp", time.Now()),
            slog.String("activity", "Receipt_OCR_Failed"),
            slog.String("operator", userID),
        )
        return
    }

    // КЕЙС Б: Всё прошло успешно
    // Фиксируем успешный шаг бизнес-процесса
    pmLogger.Info("Process_Mining_Event",
        slog.String("case_id", txID),
        slog.Time("timestamp", time.Now()),
        slog.String("activity", "Receipt_OCR_Success"), // Тот самый успешный шаг!
        slog.String("operator", userID),
    )
}

