3.3 Приложение: Объединенный пример реализации на Go (slog)
В реальном микросервисе обработчик транзакции вызывает оба логгера (system и process), сохраняя единый trace_id / case_id для сквозного аудита. Агент Vector по полю log_stream разложит этот вывод по разным таблицам ClickHouse.

package main

import (
    "context"
    "errors"
    "fmt"
    "log/slog"
    "os"
    "time"

    "://github.com"
)

// Единый JSON-обработчик в stdout, маршрутизируемый Vector
var logger = slog.New(slog.NewJSONHandler(os.Stdout, &slog.HandlerOptions{
    Level: slog.LevelInfo,
}))

// LogSystemError пишет в sys_observability.system_error_logs
func LogSystemError(ctx context.Context, service, traceID, canonicalCode, msg, stack string, observabilityJSON string) {
    logger.Error("system_exception",
        slog.String("log_stream", "system"),
        slog.Time("timestamp", time.Now().UTC()),
        slog.String("service_name", service),
        slog.String("trace_id", traceID),
        slog.String("canonical_code", canonicalCode),
        slog.String("level", "ERROR"),
        slog.String("message", msg),
        slog.String("stack_trace", stack),
        slog.String("observability_json", observabilityJSON),
    )
}

// LogProcessEvent пишет в logs.process_events (case_id == trace_id)
func LogProcessEvent(ctx context.Context, service, caseID, activity, operatorID string, attrsJSON string) {
    if attrsJSON == "" {
        attrsJSON = "null"
    }
    logger.Info("process_transition",
        slog.String("log_stream", "process"),
        slog.Time("timestamp", time.Now().UTC()),
        slog.String("service_name", service),
        slog.String("case_id", caseID),
        slog.String("activity", activity),
        slog.String("operator_id", operatorID),
        slog.String("attributes_json", attrsJSON),
    )
}

// Пример бизнес-метода с Dual-Stream Logging
func ProcessReceiptTransaction(ctx context.Context, txID uuid.UUID, userID string, imageBase64 string) error {
    service := "receipt-processor"
    idStr := txID.String()

    // 1. Фиксируем старт шага в Process Mining
    LogProcessEvent(ctx, service, idStr, "Receipt_OCR_Started", userID, `{"channel": "mobile"}`)

    // 2. Имитация вызова внешнего ИИ-шлюза
    err := callAiVisionGateway(imageBase64)
